package com.musiccatalog.exception; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.bind.MethodArgumentNotValidException; import java.time.*;
@RestControllerAdvice public class GlobalExceptionHandler { record Error(int status,String message,Instant timestamp){} private ResponseEntity<Error> response(HttpStatus s,String m){return ResponseEntity.status(s).body(new Error(s.value(),m,Instant.now()));} @ExceptionHandler(ApiException.class) ResponseEntity<Error> api(ApiException e){return response(e.status(),e.getMessage());} @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<Error> validation(MethodArgumentNotValidException e){String m=e.getBindingResult().getFieldErrors().stream().findFirst().map(x->x.getField()+": "+x.getDefaultMessage()).orElse("Invalid input");return response(HttpStatus.BAD_REQUEST,m);} @ExceptionHandler(Exception.class) ResponseEntity<Error> other(Exception e){return response(HttpStatus.INTERNAL_SERVER_ERROR,"An unexpected error occurred");} }
